def max_product(num_str: str, N: int, K: int) -> int:
    """
    Encodes the integer from a given format into a string and returns the maximum product of that number.

    Args:
    num_str (str): A string representing the integer.
    N (int): An integer representing the length of the integer.
    K (int): An integer representing the number of multiplication signs to insert.

    Returns:
    int: The maximum product that can be obtained by inserting K multiplication signs into the integer.
    """
    if N == 1:
        return int(num_str)

    # Create a list of substrings of length K
    substrings = []
    for i in range(N - K + 1):
        substrings.append(num_str[i:i + K])

    # Check if all substrings are positive
    all_positive = all(int(s) > 0 for s in substrings)

    # If all substrings are positive, return the product of the first K substrings
    if all_positive:
        return int(substrings[0]) * int(substrings[1])

    # If all substrings are negative, return the product of the last K substrings
    else:
        return int(substrings[-N + K]) * int(substrings[-N + K + 1])

