def max_product(num_str: str, N: int, K: int) -> int:
    def calculate_product(s):
        stack = []
        for char in s:
            if char == '*':
                b = stack.pop()
                c = stack.pop()
                stack.append(b * c)
            else:
                stack.append(int(char))
        return stack[0]

    def backtrack(i, n, k):
        if k == 0:
            return calculate_product(num_str[i:])
        if i >= n - k:
            return -sys.maxsize
        result = -sys.maxsize
        for j in range(i, n - k + 1):
            result = max(result, backtrack(j+1, n, k-1) * int(num_str[i:j+1]))
        return result

    return backtrack(0, N, K)

