def verify_isbn(isbn: str) -> str:
    if not isbn.isdigit() or len(isbn) not in [10]:
        return "Invalid ISBN format"

    # Calculate the ISBN checksum
    checksum = 0
    for i, char in enumerate(isbn[:-1]):
        digit = int(char)
        if i % 2 == 0:
            checksum += digit
        else:
            checksum += digit * 3

    # Adjust the checksum if it is 10
    if checksum % 10 == 0:
        correction = 0
    else:
        correction = 10 - (checksum % 10)

    # Correct the ISBN if necessary
    if correction != int(isbn[-1]):
        corrected_isbn = isbn[:-1] + str(correction)
        return corrected_isbn
    else:
        return "Right"

