    if n == 0:
        return 0
    if n == 1:
        return 1
    if w < prices[0]:
        return 0
    if n == 2 and prices[0] + prices[1] <= w:
        return 1
    if n == 2 and prices[0] + prices[1] > w:
        return 2
    min_groups = min_groups(w-prices[0], n-1, prices[1:]) + 1
    min_groups = min(min_groups, min_groups(w-prices[1], n-2, prices[2:]))
    return min_groups

def hanoi_double_iterative(n: int) -> int:
    # Iterate from 0 to n-1 to compute the minimum moves 
    # for each number of pairs
    return sum((4 ** i) for i in range(n))

def hanoi_double_iterative(n: int) -> int:
    # Since there are 2n discs in total, the number of moves required to move them
    # to the C pole following the double-disc Hanoi Tower rules is given by the formula:
    # 2 * (2^n - 1)
    return 2 * (2 ** n - 1)

def total_smoked_cigarettes(n, k):
    total = n
    while n >= k:
        total += 1
        n = (n - k) // k + 1
    return total
